// two pointers
class Solution {
public:
    int maxArea(vector<int>& height) {
        int n = height.size();
        int water = 0;
        for(int i = 0, j = n - 1; i < j;) {
            int h = height[i] < height[j] ? height[i++] : height[j--];
            int area = h * (j - i + 1);
            water = max(area,water);
        }
        return water;
    }
};


